import Handlebars from 'handlebars';
import ifCondOr from '../helper/funcs/ifCondOr.js';

Handlebars.registerHelper('ifCondOr', ifCondOr);

describe('ifCondOr Helper', () => {

  it('should return true block when at least one condition is true', () => {
    const template = Handlebars.compile('{{#ifCondOr 5 "==" 5 10 ">" 20}}At least one is true{{^}}None are true{{/ifCondOr}}');
    const result = template({});
    expect(result).toBe('At least one is true');
  });

  it('should return false block when all conditions are false', () => {
    const template = Handlebars.compile('{{#ifCondOr 5 ">" 10 3 "==" 4}}At least one is true{{^}}None are true{{/ifCondOr}}');
    const result = template({});
    expect(result).toBe('None are true');
  });

  it('should handle strict equality and inequality (=== and !==)', () => {
    const template = Handlebars.compile('{{#ifCondOr "5" "===" 5 5 "!==" 6}}At least one is true{{^}}None are true{{/ifCondOr}}');
    const result = template({});
    expect(result).toBe('At least one is true');
  });

  it('should handle "in" operator with multiple values', () => {
    const template = Handlebars.compile('{{#ifCondOr "softpro.ua" "in" "help.softpro.ua,softpro.ua" "123" "in" "456,789"}}In at least one{{^}}Not in any{{/ifCondOr}}');
    const result = template({});
    expect(result).toBe('In at least one');
  });

  it('should handle "not in" operator correctly', () => {
    const template = Handlebars.compile('{{#ifCondOr "test" "not in" "softpro.ua,help.ua" "example" "not in" "test,help"}}At least one is true{{^}}None are true{{/ifCondOr}}');
    const result = template({});
    expect(result).toBe('At least one is true');
  });

  it('should handle comparison with > and < operators', () => {
    const template = Handlebars.compile('{{#ifCondOr 10 ">" 5 3 "<" 4}}At least one is true{{^}}None are true{{/ifCondOr}}');
    const result = template({});
    expect(result).toBe('At least one is true');
  });

  it('should handle logical operators && and ||', () => {
    const template = Handlebars.compile('{{#ifCondOr true "&&" false false "||" true}}At least one is true{{^}}None are true{{/ifCondOr}}');
    const result = template({});
    expect(result).toBe('At least one is true');
  });

  it('should handle array intersection (&)', () => {
    const template = Handlebars.compile('{{#ifCondOr arr1 "&" arr2}}Intersection found{{^}}No intersection{{/ifCondOr}}');
    const result = template({ arr1: [1, 2, 3], arr2: [3, 4, 5] });
    expect(result).toBe('Intersection found');
  });

  it('should handle no intersection with & operator', () => {
    const template = Handlebars.compile('{{#ifCondOr arr1 "&" arr2}}Intersection found{{^}}No intersection{{/ifCondOr}}');
    const result = template({ arr1: [1, 2], arr2: [3, 4] });
    expect(result).toBe('No intersection');
  });

  it('should handle substring inclusion (~) and exclusion (!~)', () => {
    const templateContains = Handlebars.compile('{{#ifCondOr "softpro" "~" "soft"}}Contains substring{{^}}Does not contain substring{{/ifCondOr}}');
    const resultContains = templateContains({});
    expect(resultContains).toBe('Contains substring');

    const templateDoesNotContain = Handlebars.compile('{{#ifCondOr "softpro" "!~" "help"}}Does not contain substring{{^}}Contains substring{{/ifCondOr}}');
    const resultDoesNotContain = templateDoesNotContain({});
    expect(resultDoesNotContain).toBe('Does not contain substring');
  });

  it('should handle date range with "period" operator', () => {
    const template = Handlebars.compile('{{#ifCondOr "2023-01-01" "period" "2025-01-01"}}Within period{{^}}Outside period{{/ifCondOr}}');
    const result = template({});
    expect(result).toBe('Within period');
  });

  it('should return false block for date outside period', () => {
    const template = Handlebars.compile('{{#ifCondOr "2019-01-01" "period" "2022-01-01"}}Within period{{^}}Outside period{{/ifCondOr}}');
    const result = template({});
    expect(result).toBe('Outside period');
  });

  it('should handle complex conditions with multiple true and false checks', () => {
    const template = Handlebars.compile('{{#ifCondOr 5 "==" 5 "test" "!~" "fail" "softpro.ua" "in" "softpro.ua,help.ua"}}Complex case true{{^}}Complex case false{{/ifCondOr}}');
    const result = template({});
    expect(result).toBe('Complex case true');
  });

  it('should return false block if all complex conditions fail', () => {
    const template = Handlebars.compile('{{#ifCondOr 5 "!=" 5 "test" "!~" "test" "example" "in" "softpro.ua,help.ua"}}Complex case true{{^}}Complex case false{{/ifCondOr}}');
    const result = template({});
    expect(result).toBe('Complex case false');
  });

  it('should handle unsupported operator and render the inverse block', () => {
    const template = Handlebars.compile('{{#ifCondOr 5 "unknown" 5}}This will not be displayed{{^}}Unsupported Operator{{/ifCondOr}}');
    const result = template({});
    expect(result).toBe('Unsupported Operator');
  });

  it('should return true block when all conditions are true (array intersection and equality)', () => {
    const template = Handlebars.compile('{{#ifCondOr groupList "&" "3126250868588938939,2256063440420341476,3243057626522584083" userType "==" "admin"}}1{{^}}0{{/ifCondOr}}');
    const result = template({
      groupList: ['2256063440420341476'],
      userType: 'admin'
    });
    expect(result).toBe('1');
  });
});
